    use sha2::Digest;
    let mut hasher = sha2::Sha256::new();
    hasher.update(data);
    let result: sha2::digest::Output<sha2::Sha256> = hasher.finalize();
    let actual = format!("{result:x}");
    if actual != expected_hex.to_lowercase() {
        return Err(format!("expected {expected_hex}, got {actual}"));
    }
    Ok(())
}

